284-
285-  if (hit.bottom) {
286-    if (m_physic.get_velocity_y() > clink_threshold && !m_last_hit.bottom)
287-        SoundManager::current()->play("sounds/coin2.ogg", get_pos());
288-    if (m_physic.get_velocity_y() > 200) {// lets some coins bounce
289-      m_physic.set_velocity_y(-99);
290-    } else {
291-      m_physic.set_velocity_y(0);
292-    }
293-  }
294-  if (hit.right || hit.left) {
295-    if ((m_physic.get_velocity_x() > clink_threshold ||
296-         m_physic.get_velocity_x()< -clink_threshold) &&
297-         hit.right != m_last_hit.right && hit.left != m_last_hit.left)
298-      SoundManager::current()->play("sounds/coin2.ogg", get_pos());
299-    m_physic.set_velocity_x(-m_physic.get_velocity_x());
300-  }
301-  if (hit.top) {
302-    if (m_physic.get_velocity_y() < -clink_threshold && !m_last_hit.top)
303-      SoundManager::current()->play("sounds/coin2.ogg", get_pos());
304-    m_physic.set_velocity_y(-m_physic.get_velocity_y());
305-  }
